  /* ---------- import ---------- */
  function openImport(kind) { pendingFile = null; ['im-buyer', 'im-title', 'im-due', 'im-text', 'im-ref', 'im-email'].forEach(i => $('#' + i).value = ''); $('#im-owner').value = me(); $('#im-preview').textContent = ''; $('#im-go').dataset.kind = kind; $('#m-import h2').textContent = kind === 'tender' ? 'New tender / bid' : 'New questionnaire'; $('#im-bidfields').classList.toggle('hidden', kind !== 'tender'); $('#im-sub').textContent = kind === 'tender' ? 'Start with the first document of the pack (ITT, specification, questionnaire or pricing schedule); add the rest from the workspace. Requirements, weightings, deadlines and questions are extracted automatically.' : "Upload the buyer's Excel or Word questionnaire, or paste the questions from a procurement portal. ALICE drafts every answer from your approved library; nothing leaves iMS OS."; $('#m-import').classList.add('open'); }
